bool anima_phrase_is_filler_lang(const char *lang, const char *w)
{
    const char *const *f = k_fill_it;
    if (lang && !strcmp(lang, "en")) f = k_fill_en;
    else if (lang && !strcmp(lang, "es")) f = k_fill_es;
    else if (lang && !strcmp(lang, "fr")) f = k_fill_fr;
    else if (lang && !strcmp(lang, "de")) f = k_fill_de;
    for (; *f; f++) if (!strcmp(*f, w)) return true;
    return false;
}

bool anima_phrase_is_filler(bool en, const char *w) { return anima_phrase_is_filler_lang(en ? "en" : "it", w); }

static int cmp(const void *k, const void *e) { return strcmp((const char *)k, ((const anima_phrase_t *)e)->key); }

const char *anima_phrase_lookup(const char *key)
{
    const anima_phrase_t *p = (const anima_phrase_t *)bsearch(key, k_phrases, sizeof k_phrases / sizeof k_phrases[0],
                                                           sizeof k_phrases[0], cmp);
    return p ? p->canon : NULL;
}

int anima_phrase_count(void) { return (int)(sizeof k_phrases / sizeof k_phrases[0]); }
